  crop: { growth_days: null, yield: 2, planted: true, requires_water: true }, npc: { dialogue: 'Hello, traveler.', quest_type: 'none', required_count: 1, reward: 5 },
  water: { fishing_probability: null, fish_value: 1 }, enemy: { health: 2, damage: 1, speed: 12, patrol_range: 32 }, portal: { destination_x: 0, destination_y: 0 },
