    const abort = new AbortController(); void getConsoleStudioDocument(project.project_id, { signal: abort.signal }).then(value => { if (!abort.signal.aborted) accept(value); }).catch(caught => { if (!abort.signal.aborted && safe()) setError(caught.message); });
