      if (sourceDirty) { const source = { op: 'replace_source' as const, path: sourcePath, content: sourceText }; const index = ops.findIndex(edit => edit.op === 'replace_source' && edit.path === sourcePath); if (index >= 0) ops[index] = source; else ops.push(source); }
      const exportIndex = ops.findIndex(edit => edit.op === 'materialize_assets'); if (exportIndex >= 0) ops.push(ops.splice(exportIndex, 1)[0]);
      if (ops.some(edit => edit.op === 'replace_source' && typeof edit.content === 'string' && new TextEncoder().encode(edit.content).byteLength > 1024 * 1024)) throw new Error('A source file may contain up to 1 MB of UTF-8 text.');
      const fingerprint = JSON.stringify({ version: issued.project.version, manifest: issued.manifest_digest, ops });
